// Memory mapped buffers
#define _K2              ((uint8_t *)_K2)                    // u8[3667552] (3667552 bytes)
#define _K1              ((uint8_t *)(_state + 0x00000010))  // u8[1632256] (1632256 bytes)
#define _K5              ((int8_t *)(_state + 0x00000000))   // s8[8] (8 bytes)
#define _K3              ((int8_t *)(_buffer + 0x000003e9))  // s8[150528] (150528 bytes)
#define _K4              ((int8_t *)(_buffer + 0x00000000))  // d8[1001] (1001 bytes)

